// Parcours pédagogique local : contrôle de forme et projection de destinataires fictifs.
// Aucun enregistrement métier, envoi externe ou contrôle d'identité de production.
const donnees = $input.first().json.body;
const valide = donnees && typeof donnees === 'object'
  && typeof donnees.id_evenement === 'string' && donnees.id_evenement.startsWith('EVT-DEMO-')
  && donnees.type === 'demande.recue'
  && typeof donnees.demande_id === 'string' && donnees.demande_id.startsWith('DEMO-')
  && typeof donnees.prestation === 'string' && donnees.prestation.trim().length > 0
  && ['flexible', 'imposee'].includes(donnees.flexibilite);
if (!valide) {
  return [{ json: { code_http: 422, resultat: { simulation: true, erreur: 'EVENEMENT_DEMO_INVALIDE' } } }];
}
const destinataires = ['COMPTE-DEMO-SECRETARIAT', 'COMPTE-DEMO-DIRECTION-1', 'COMPTE-DEMO-DIRECTION-2'];
return [{ json: {
  code_http: 200,
  resultat: {
    simulation: true,
    id_evenement: donnees.id_evenement,
    demande_id: donnees.demande_id,
    etat_demande: 'recue_non_decidee',
    prestation: donnees.prestation.trim(),
    date_demandee: donnees.date_demandee || null,
    flexibilite: donnees.flexibilite,
    notifications_fictives: destinataires.map(compte => ({ destinataire: compte, lue: false })),
    envoi_externe: false,
    dedoublonnage_durable: false
  }
} }];
